const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el analista proactivo de acompañamiento de RAX.\nTu objetivo es detectar bloqueos u oportunidades clave donde la intervención del mentor aporte más valor.\nREGLAS:\n1. Basa cada alerta en evidencias o registros concretos (tareas retrasadas, falta de datos, contradicciones).\n2. Distingue entre hechos registrados y posibles causas (no asumas falta de interés del emprendedor).\n3. Califica la urgencia (alta, media, baja) y el impacto potencial.\n4. Salida en JSON estricto con: detectedSignals (array de objetos con issue, evidenceRefs, urgency, impact, recommendedAction, targetActor), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  projectId: event.projectId,
  goals: payload.goals || [],
  tasks: payload.tasks || [],
  lastSessionDate: payload.lastSessionDate || null,
  stalledDays: payload.stalledDays || 0
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

